-- Existing scores are invalidated by the existing question-change trigger.
begin;
update public.quizzes set questions=questions || '[{"id": "1f918be4-f4b9-5dbb-89cd-526a56c648d9", "prompt": "How does y = x² + 3 compare with y = x²?", "options": ["It shifts 3 units up", "It shifts 3 units right", "It opens downwards", "It becomes a straight line"], "correctIndex": 0, "explanation": "Adding 3 increases every y-value by 3, so the graph shifts upwards."}, {"id": "cb1ad288-bd73-5e91-9e60-53215d9f009c", "prompt": "Which line is the axis of symmetry of y = x²?", "options": ["y = 1", "x = 1", "y = x", "x = 0"], "correctIndex": 3, "explanation": "The points at x and -x have the same y-value, so reflection across x = 0 leaves the graph unchanged."}]'::jsonb where id='54371eb4-7bfa-42ec-bac9-707929c127a6'::uuid and jsonb_array_length(questions)=3;
update public.quizzes set questions=questions || '[{"id": "8e9db3cc-9ff0-56b3-9305-44f3127c003d", "prompt": "Why does the speaker look down one road before choosing?", "options": ["To count the trees", "To search for another traveller", "To see as far ahead as possible despite limited knowledge", "To find the shortest path back home"], "correctIndex": 2, "explanation": "The limited view supports the idea that we cannot know every consequence before making a choice."}, {"id": "acc1e34b-b4dd-5326-b942-c468ead1d3c3", "prompt": "What does the repeated first-person perspective give the poem?", "options": ["A personal account of making and remembering a choice", "An objective map of the forest", "The thoughts of every traveller", "A set of scientific observations"], "correctIndex": 0, "explanation": "The first-person speaker presents a subjective memory and anticipates how that memory may be retold."}]'::jsonb where id='a631f2d2-618f-4ab7-b30b-15f7e5b0d9b4'::uuid and jsonb_array_length(questions)=3;
update public.quizzes set questions=questions || '[{"id": "7a2c41c6-e2bd-5370-90f4-ce4c8a2dbe68", "prompt": "How many lines are in each stanza of the poem?", "options": ["Four", "Five", "Six", "Eight"], "correctIndex": 1, "explanation": "Each of the four stanzas has five lines, matching the ABAAB rhyme pattern."}, {"id": "ba12cd1a-e57c-5141-b952-eb22d1816411", "prompt": "Why is the future retelling important to the poem?", "options": ["It proves one road was dangerous", "It removes all uncertainty", "It gives directions to future walkers", "It invites us to question how people explain past choices"], "correctIndex": 3, "explanation": "The speaker imagines telling the story later, drawing attention to the difference between making a choice and giving it meaning afterwards."}]'::jsonb where id='c3ae81ab-433c-4abe-89b0-9141acf91875'::uuid and jsonb_array_length(questions)=3;
commit;
